import { escapeMarkdown } from 'discord.js';
/**
 * HTML transcript of a ticket, styled like Discord. Merged from the old Midtown Desk bot.
 * Everything a user typed is HTML-escaped, and only Discord's own attachment URLs are linked.
 */
const CSS = `body{margin:0;background:#313338;color:#dbdee1;font-family:'gg sans','Segoe UI',Helvetica,Arial,sans-serif;font-size:15px}
.top{background:#2b2d31;padding:20px 24px;border-bottom:1px solid #1e1f22}
.top h1{margin:0 0 8px;font-size:20px;color:#f2f3f5}
.meta{display:flex;flex-wrap:wrap;gap:6px 22px;color:#b5bac1;font-size:13px}
.meta b{color:#f2f3f5}
.log{padding:12px 0}
.msg{display:flex;gap:14px;padding:6px 24px}
.msg:hover{background:#2e3035}
.av{width:40px;height:40px;border-radius:50%;flex-shrink:0}
.name{font-weight:600;color:#f2f3f5}
.tag{background:#5865f2;color:#fff;font-size:10px;padding:1px 5px;border-radius:3px;margin-left:6px;vertical-align:middle}
.ts{color:#949ba4;font-size:12px;margin-left:8px}
.ct{line-height:1.4;word-wrap:break-word}
.embed{border-left:4px solid #5865f2;background:#2b2d31;border-radius:4px;padding:8px 12px;margin-top:6px;max-width:520px}
.et{font-weight:600;color:#f2f3f5;margin-bottom:4px}
.f{margin-top:6px}
img.att{max-width:400px;max-height:300px;border-radius:6px;margin-top:6px;display:block}
a{color:#00a8fc}
.foot{color:#949ba4;font-size:12px;padding:16px 24px;border-top:1px solid #1e1f22}`;
const escapeHtml = (text) => text.replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch]);
const br = (text) => escapeHtml(text).replace(/\n/g, '<br>');
const time = (date) => date.toUTCString().replace('GMT', 'UTC');
/** Read the channel oldest-first and render a single self-contained HTML file plus its message count. */
export async function buildTranscript(channel, ticket, guild) {
    const rows = [];
    let count = 0;
    let before;
    for (;;) {
        const batch = await channel.messages.fetch({ limit: 100, ...(before ? { before } : {}) }).catch(() => null);
        if (!batch?.size)
            break;
        const messages = [...batch.values()].sort((a, b) => a.createdTimestamp - b.createdTimestamp);
        // Newest-first pages are collected first, then reversed at the end, so a long ticket is not held twice.
        for (const message of messages) {
            count++;
            const extras = [];
            for (const item of message.embeds) {
                const fields = (item.fields ?? []).map(f => `<div class="f"><b>${escapeHtml(f.name)}</b><br>${br(f.value)}</div>`).join('');
                extras.push(`<div class="embed"><div class="et">${escapeHtml(item.title ?? '')}</div><div>${br(item.description ?? '')}</div>${fields}</div>`);
            }
            for (const file of message.attachments.values()) {
                const url = escapeHtml(file.url);
                const image = (file.contentType ?? '').startsWith('image/');
                extras.push(image ? `<a href="${url}"><img class="att" src="${url}" alt=""></a>` : `<div><a href="${url}">📎 ${escapeHtml(file.name)}</a></div>`);
            }
            rows.push(`<div class="msg"><img class="av" src="${escapeHtml(message.author.displayAvatarURL({ extension: 'png', size: 64 }))}" alt="">`
                + `<div><div><span class="name">${escapeHtml(message.author.displayName ?? message.author.username)}</span>`
                + `${message.author.bot ? '<span class="tag">BOT</span>' : ''}<span class="ts">${time(message.createdAt)}</span></div>`
                + `<div class="ct">${br(message.cleanContent ?? '')}</div>${extras.join('')}</div></div>`);
        }
        before = messages[0].id;
        if (batch.size < 100)
            break;
    }
    rows.reverse();
    const opener = await guild.members.fetch(ticket.user_id).catch(() => null);
    const claimer = ticket.claimed_by ? await guild.members.fetch(ticket.claimed_by).catch(() => null) : null;
    const number = ticket.number.toString().padStart(4, '0');
    const html = `<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ticket #${number} - ${escapeHtml(guild.name)}</title><style>${CSS}</style></head>
<body>
<div class="top"><h1>🎫 Ticket #${number} · ${escapeHtml(ticket.type)}</h1>
<div class="meta">
<span><b>Server:</b> ${escapeHtml(guild.name)}</span>
<span><b>Opened by:</b> ${escapeHtml(opener?.user.tag ?? ticket.user_id)}</span>
<span><b>Claimed by:</b> ${escapeHtml(claimer?.user.tag ?? 'Nobody')}</span>
<span><b>Subject:</b> ${escapeHtml(ticket.subject ?? '')}</span>
<span><b>Messages:</b> ${count}</span>
</div></div>
<div class="log">${rows.join('')}</div>
<div class="foot">Transcript generated by Ghost Vanguard on ${time(new Date())}</div>
</body></html>`;
    return { html, count };
}
/** Kept for the transcript header, so long subjects cannot break the layout. */
export const transcriptSubject = (subject) => escapeMarkdown(subject).slice(0, 300);
